<template>
    <div class="h-100 w-100">
        <!-- 當 loading 為 true 時顯示 Loading 畫面 -->
        <div
            v-if="loading"
            class="d-flex align-items-center justify-content-center h-100 w-100 flex-column loading_background"
        >
            <div class="loading">
                <div></div>
                <div></div>
                <div></div>
                <div></div>
            </div>

            <div class="mt-3">LOADING...</div>
        </div>
        <!-- 當 loading 為 false 時才顯示頁面內容 -->
        <router-view v-else class="h-100 w-100"></router-view>
    </div>
</template>

<script>
import { getAuth } from 'firebase/auth'
import api from '@/axios/axios.ts'
export default {
    components: {},
    computed: {},
    data() {
        return {
            loading: true, // 初始化為 true，表示正在加載中
        }
    },
    methods: {
        async initData() {
            try {
                this.loading = true
                await Promise.all([
                    this.getTypeList(),
                    this.getAnnoList('all', 5, 'views'),
                ])
            } catch (error) {
                console.error('Error initializing data:', error)
            } finally {
                this.loading = false
            }
        },
        async getTypeList() {
            try {
                const response = await api.get('/getTypeList')
                this.$store.state.generalInfo.typeList = response.data.typeList
                console.log('typeList:', this.$store.state.generalInfo.typeList)
            } catch (error) {
                console.error('Error fetching type list:', error)
            }
        },
        async getAnnoList(selectType, limit, orderBy) {
            try {
                const response = await api.post('/getAnnoHeader', {
                    selectType,
                    limit,
                    orderBy,
                })
                this.$store.state.generalInfo.annoList = response.data.data
            } catch (error) {
                console.error('Error fetching announcement list:', error)
            }
        },
    },
    created() {
        this.initData()
        const auth = getAuth()
        auth.onAuthStateChanged(user => {
            if (user) {
                // 获取用户的 authToken
                user.getIdToken(true)
                    .then(idToken => {
                        // 处理 token
                        console.log('Auth Token:', idToken)
                        this.$store.state.idToken = idToken
                    })
                    .catch(error => {
                        console.error('Error getting token:', error)
                    })
            } else {
                // User is signed out
                console.log('not login')
            }
        })
    },
    beforeMount() {},
    mounted() {},
}
</script>

